let corpo = {};
try { corpo = insomnia.response.json(); } catch (e) { corpo = {}; }

insomnia.test("Status HTTP 200", () => {
  insomnia.expect(insomnia.response.code).to.eql(200);
});

insomnia.test("Resposta é uma lista de dias, sem meta", () => {
  insomnia.expect(corpo.data).to.be.an('array');
  insomnia.expect(corpo).to.not.have.property('meta');
});

insomnia.test("Todo dia pertence ao mês pedido", () => {
  const mes = insomnia.environment.get('mes');
  corpo.data.forEach((d) => {
    insomnia.expect(d.dia).to.match(/^\d{4}-\d{2}-\d{2}$/);
    insomnia.expect(d.dia.startsWith(mes)).to.eql(true);
  });
});

insomnia.test("Dias em ordem crescente e sem repetição", () => {
  const dias = corpo.data.map((d) => d.dia);
  insomnia.expect(dias).to.eql([...new Set(dias)].sort());
});

insomnia.test("Cada dia traz ao menos um empréstimo com os campos esperados", () => {
  corpo.data.forEach((d) => {
    insomnia.expect(d.emprestimos).to.be.an('array').and.not.empty;
    d.emprestimos.forEach((e) => insomnia.expect(e).to.include.all.keys('id', 'ferramenta_nome', 'ferramenta_codigo', 'colaborador_nome', 'setor_id', 'setor_nome', 'ramal'));
  });
});

insomnia.test("Código da ferramenta tem 6 dígitos (ou traço) e ramal é null", () => {
  corpo.data.forEach((d) => d.emprestimos.forEach((e) => {
    insomnia.expect(e.ferramenta_codigo).to.match(/^(\d{6}|—)$/);
    insomnia.expect(e.ramal).to.eql(null);
  }));
});

